var calc_output = [];

var cardiac = parseFloat(cardiac)
var resp = parseFloat(resp)
var stroke = parseFloat(stroke)
var mi = parseFloat(mi)
var id = parseFloat(id)
var rheum = parseFloat(rheum)
var malignancy = parseFloat(malignancy)
var myelo = parseFloat(myelo)
var neph = parseFloat(neph)
var hxvte = parseFloat(hxvte)
var hyper = parseFloat(hyper)
var immob = parseFloat(immob)
var travel = parseFloat(travel)
var age = parseFloat(age)
var obese = parseFloat(obese)
var venousinsuf = parseFloat(venousinsuf)
var preg = parseFloat(preg)
var hormone = parseFloat(hormone)
var dehydration = parseFloat(dehydration)


var score = cardiac + resp + stroke + mi + id + rheum + malignancy + myelo + neph + hxvte + hyper + immob + travel + age + obese + venousinsuf + preg + hormone + dehydration

var group = ''
var risk = ''
var recommendation = '' 


if (score <3) {
	group = 'Low'
	risk = '0.6'
	recommendation = 'VTE prophylaxis NOT indicated'
} else if (score >= 3) {
	group = 'High'
	risk = '3.2'
	recommendation = 'VTE prophylaxis indicated (presuming no contraindications)'
}
//results 

//results 
calc_output.push({
    name: 'mini',
    value: group,
    value_text: 'risk',
    message: recommendation
    });
calc_output.push({
    name: '10073_Geneva Score (VTE Prophylaxis)_result (score)',
    value: score,
    value_text: 'points',
    message: 'Geneva Risk Score for VTE Prophylaxis'
    });
calc_output.push({
    name: '10073_Geneva Score (VTE Prophylaxis)_result (risk)',
    value: risk, 
    value_text: '%',
    message: 'VTE risk (composite of symptomatic VTE or 90-day VTE mortality)'
});
calc_output.push({
    name: '10073_Geneva Score (VTE Prophylaxis)_interpretation',
    value: group, 
    value_text: 'risk',
    message: recommendation
});
